Lemma vis_rep_nret : forall L A (ms : machine_state) (eff : SyscallEffect),
  eff_copies eff = [] -> eff_writes eff = [] ->
  (forall a : word, shreg (bv_unsigned a) -> zeros_cover (eff_unmaps eff) a = false) ->
